  5| import { computeTotals, type Totals } from './pricing';
  6| import { ShopError } from './shop-error';
  7| 
  8| export const MAX_QUANTITY = 10;
  9| 
 10| export const quantitySchema = z.coerce.number().int().min(1).max(MAX_QUANTITY);
 11| export const couponCodeSchema = z
 12|   .string()
 13|   .trim()
 14|   .min(1)
 15|   .max(40)
 16|   .transform((code) => code.toUpperCase());
 17| 
 18| export interface CartLine {
 19|   productId: string;
 20|   slug: string;
 21|   name: string;
 22|   unitPriceCents: number;
 23|   quantity: number;
 24|   stock: number;
 25| }
 26| 
 27| export interface CartView {
 28|   lines: CartLine[];
 29|   coupon: { code: string; percentOff: number } | null;
 30|   totals: Totals;
 31| }
 32| 
 33| export async function getCart(prisma: PrismaClient, userId: string): Promise<CartView> {
 34|   const cart = await prisma.cart.findUnique({
 35|     where: { userId },
 36|     include: { coupon: true, items: { include: { product: true } } },
 37|   });
 38|   const lines: CartLine[] = (cart?.items ?? [])
 39|     .map((item) => ({
 40|       productId: item.productId,
 41|       slug: item.product.slug,
 42|       name: item.product.name,
 43|       unitPriceCents: item.product.priceCents,
 44|       quantity: item.quantity,
 45|       stock: item.product.stock,
 46|     }))
 47|     .sort((a, b) => a.name.localeCompare(b.name));
 48|   const coupon =
 49|     cart?.coupon && cart.coupon.active
 50|       ? { code: cart.coupon.code, percentOff: cart.coupon.percentOff }
 51|       : null;
 52|   return { lines, coupon, totals: computeTotals(lines, coupon?.percentOff ?? null) };
 53| }
