 59| export async function addToCart(
 60|   prisma: PrismaClient,
 61|   userId: string,
 62|   productId: string,
 63|   rawQuantity: unknown,
 64| ): Promise<void> {
 65|   const quantity = quantitySchema.safeParse(rawQuantity);
 66|   if (!quantity.success) throw new ShopError('invalid_input', 'Cantidad no válida.');
 67|   const product = await prisma.product.findUnique({ where: { id: productId } });
 68|   if (product === null) throw new ShopError('not_found', 'Ese producto no existe.');
 69|   await ensureCart(prisma, userId);
 70|   const existing = await prisma.cartItem.findUnique({
 71|     where: { userId_productId: { userId, productId } },
 72|   });
 73|   const next = Math.min((existing?.quantity ?? 0) + quantity.data, MAX_QUANTITY);
 74|   if (next > product.stock) throw new ShopError('out_of_stock', 'No hay stock suficiente.');
 75|   await prisma.cartItem.upsert({
 76|     where: { userId_productId: { userId, productId } },
 77|     create: { userId, productId, quantity: next },
 78|     update: { quantity: next },
 79|   });
 80| }
