 82| export async function setCartQuantity(
 83|   prisma: PrismaClient,
 84|   userId: string,
 85|   productId: string,
 86|   rawQuantity: unknown,
 87| ): Promise<void> {
 88|   const quantity = quantitySchema.safeParse(rawQuantity);
 89|   if (!quantity.success) throw new ShopError('invalid_input', 'Cantidad no válida.');
 90|   const item = await prisma.cartItem.findUnique({
 91|     where: { userId_productId: { userId, productId } },
 92|     include: { product: true },
 93|   });
 94|   if (item === null) throw new ShopError('not_found', 'Ese producto no está en tu carrito.');
 95|   if (quantity.data > item.product.stock) {
 96|     throw new ShopError('out_of_stock', 'No hay stock suficiente.');
 97|   }
 98|   await prisma.cartItem.update({
 99|     where: { userId_productId: { userId, productId } },
100|     data: { quantity: quantity.data },
101|   });
102| }
