104| export async function removeFromCart(
105|   prisma: PrismaClient,
106|   userId: string,
107|   productId: string,
108| ): Promise<void> {
109|   await prisma.cartItem.deleteMany({ where: { userId, productId } });
110| }
111| 
112| export async function applyCoupon(
113|   prisma: PrismaClient,
114|   userId: string,
115|   rawCode: unknown,
116| ): Promise<void> {
117|   const code = couponCodeSchema.safeParse(rawCode);
118|   if (!code.success) throw new ShopError('coupon_invalid', 'Ese cupón no es válido.');
119|   const coupon = await prisma.coupon.findUnique({ where: { code: code.data } });
120|   if (coupon === null || !coupon.active) {
121|     throw new ShopError('coupon_invalid', 'Ese cupón no es válido.');
122|   }
123|   const used = await prisma.couponRedemption.findUnique({
124|     where: { couponId_userId: { couponId: coupon.id, userId } },
125|   });
126|   if (used !== null) throw new ShopError('coupon_used', 'Ya has usado ese cupón.');
127|   await ensureCart(prisma, userId);
128|   await prisma.cart.update({ where: { userId }, data: { couponId: coupon.id } });
129| }
